    ('0e4e4bfd-6702-4adc-b6be-c2e47764cfef'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26c-s001:0e4e4bfd-6702-4adc-b6be-c2e47764cfef:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "The stored 500 BC is wrong: Gough''s Cave''s first attested occupation is the Late Upper Palaeolithic (Magdalenian) one, and Wikipedia (Skull cup article) puts it at 12,750 BC. But every other source I could read (NHM, PLOS ONE, UBSS Cave Burial gazetteer, Cheddar Gorge, Bradshaw Foundation) gives it only as about 14,700 years ago or cal BP, so no second independent family states a readable BC year, century or millennium, and the field is cleared.", "value_page": null}]'::jsonb),
