    ('41eb7a6d-7eb0-4842-b25a-52cca7b3355e'::uuid, 'period_start', '-5000', NULL, 'fields-wd1-2026-09-26c-s001:41eb7a6d-7eb0-4842-b25a-52cca7b3355e:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-5000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "Cadw, Coflein (RCAHMW), Wikipedia and the Megalithic Portal describe Tŷ Newydd only as a Neolithic chambered tomb, later reused by Beaker users; none gives a construction year or century, and the stored -5000 predates the Neolithic in Wales. With no two sources dating the start, the field is emptied.", "value_page": null}]'::jsonb),
