    ('49b5ec85-112e-4ba8-a8c7-62cf48f745ae'::uuid, 'period_start', '500', '300', 'fields-wd1-2026-09-26c-s001:49b5ec85-112e-4ba8-a8c7-62cf48f745ae:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''500'' -> ''300''', '[{"source": "https://es.wikipedia.org/wiki/Cancu%C3%A9n", "url": "https://es.wikipedia.org/wiki/Cancu%C3%A9n", "quote": "y que fue ocupado desde el 300 al 950 d. C., alcanzando su máximo esplendor en la segunda mitad del siglo VIII d. C.", "outcome": "found"}, {"source": "https://archive.archaeology.org/online/news/cancuen/", "url": "https://archive.archaeology.org/online/news/cancuen/", "quote": "The city was ruled by one of the Maya world''s oldest dynasties, one that was established sometime around A.D. 300.", "outcome": "found"}, {"source": "https://prensacomunitaria.org/2025/01/sitio-arqueologico-cancuen-en-sayaxche-peten-abandono-y-deterioro-historico/", "url": "https://prensacomunitaria.org/2025/01/sitio-arqueologico-cancuen-en-sayaxche-peten-abandono-y-deterioro-historico/", "quote": "Este sitio arqueológico, ubicado al sur de Sayaxché, Petén, estuvo habitado entre los años 300 y 950 d.C., alcanzando su máximo esplendor en el siglo VIII d.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "Spanish Wikipedia and Prensa Comunitaria date Cancuén''s occupation from AD 300 to 950, and Archaeology magazine (reporting Demarest''s Vanderbilt project) says its dynasty was established around AD 300; the start is AD 300, in the 1-500 AD bucket rather than the stored 500.", "value_page": null}]'::jsonb),
    ('4dc60f9f-66cf-4a4a-9c47-bf24cc0d618d'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26c-s001:4dc60f9f-66cf-4a4a-9c47-bf24cc0d618d:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4dc60f9f-66cf-4a4a-9c47-bf24cc0d618d'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26c-s001:4dc60f9f-66cf-4a4a-9c47-bf24cc0d618d:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the carving of the Gate of the Sun itself: Wikipedia gives only the Tiwanaku culture''s floruit (AD 500-950), a World History Encyclopedia caption says c. 300 CE for the Kalasasaya entrance, UCLA''s SAIS database says only ''Middle Horizon'', and the gate is known to have been moved from its unknown original site; two independent sources do not agree on a start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('5987b6e6-6da5-4f79-8ca2-674bfc7b3be9'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26c-s001:5987b6e6-6da5-4f79-8ca2-674bfc7b3be9:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start 201 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(201) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5987b6e6-6da5-4f79-8ca2-674bfc7b3be9'::uuid, 'period_start', '-100', '201', 'fields-wd1-2026-09-26c-s001:5987b6e6-6da5-4f79-8ca2-674bfc7b3be9:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-100'' -> ''201''', '[{"source": "https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=81470", "url": "https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=81470", "quote": "It is believed to have been constructed in the 3rd to 4th centuries.", "outcome": "found"}, {"source": "https://encykorea.aks.ac.kr/Article/E0018833", "url": "https://encykorea.aks.ac.kr/Article/E0018833", "quote": "토성을 축조한 연대의 상한은 3세기 후반 경으로 추정된다.", "outcome": "found"}, {"source": "https://ko.wikipedia.org/wiki/%EB%AA%BD%EC%B4%8C%ED%86%A0%EC%84%B1", "url": "https://ko.wikipedia.org/wiki/%EB%AA%BD%EC%B4%8C%ED%86%A0%EC%84%B1", "quote": "3세기 초에 축조되었다.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "The Korea Tourism Organization, the Encyclopedia of Korean Culture and Korean Wikipedia all date the construction of the Baekje earthen fortress to the 3rd century AD (the encyclopedia puts the earliest possible date in the late 3rd century from Western Jin ceramics in the wall); the stored -100 lies in the wrong bucket, so it becomes 201.", "value_page": null}]'::jsonb),
    ('68859b06-2135-4711-a160-da003d18ccca'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26c-s001:68859b06-2135-4711-a160-da003d18ccca:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('68859b06-2135-4711-a160-da003d18ccca'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26c-s001:68859b06-2135-4711-a160-da003d18ccca:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "The Taiwanese sources (Hualien tourism, Hualien Cultural Affairs Bureau, Indigenous encyclopedia) date the pillars and the Qilin-culture site only as about 3,000 years before present, which is not a year; the only page giving a year, the Megalithic Portal, says ''about 3000 BC'', contradicting them. No two independent sources give a year, so the field is emptied.", "value_page": null}]'::jsonb),
    ('68859b06-2135-4711-a160-da003d18ccca'::uuid, 'site_type', 'Megalithic stones', 'Standing stone', 'fields-wd1-2026-09-26c-s001:68859b06-2135-4711-a160-da003d18ccca:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''Megalithic stones'' -> ''Standing stone''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=31823", "url": "https://www.megalithic.co.uk/article.php?sid=31823", "quote": "Two large Neolithic (about 3000 BC) standing stones, between 5 and 7 meters tall.", "outcome": "found"}, {"source": "https://tour-hualien.hl.gov.tw/en/TourList.aspx?n=169&sms=12369&_CSN=84", "url": "https://tour-hualien.hl.gov.tw/en/TourList.aspx?n=169&sms=12369&_CSN=84", "quote": "Saoba Ruin includes two monoliths standing right next to each other at 5.75 m and 3.99m, respectively.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Saoba_Stone_Pillars", "url": "https://en.wikipedia.org/wiki/Saoba_Stone_Pillars", "quote": "The site consists of two adjacent stone pillars", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal classes Satokoay as two standing stones, Hualien County''s tourism site describes two monoliths standing side by side, and Wikipedia says the site consists of two adjacent stone pillars; the most specific canonical type for this is Standing stone, more precise than the generic Megalithic stones.", "value_page": null}]'::jsonb),
    ('6c7352e9-2e99-4dd7-b2c8-93a883b69d4f'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26c-s001:6c7352e9-2e99-4dd7-b2c8-93a883b69d4f:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -17 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-17) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('6c7352e9-2e99-4dd7-b2c8-93a883b69d4f'::uuid, 'period_start', '1', '-17', 'fields-wd1-2026-09-26c-s001:6c7352e9-2e99-4dd7-b2c8-93a883b69d4f:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''1'' -> ''-17''', '[{"source": "https://www.trier-info.de/sehenswuerdigkeiten/roemerbruecke", "url": "https://www.trier-info.de/sehenswuerdigkeiten/roemerbruecke", "quote": "Zwei vorherige Holzbrücken an diesem Standort, von der die älteste unmittelbar mit der Stadtgründung 17 v.Chr. in Verbindung steht, wurden ab 144 n.Chr. durch die heutigen Steinpfeiler ersetzt.", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/augusta-treverorum-trier/trier-photos/trier-bridge/", "url": "https://www.livius.org/articles/place/augusta-treverorum-trier/trier-photos/trier-bridge/", "quote": "There is a dendrochonological date of 17 BCE for one of the pieces of wood of the bridge. The monument was rebuilt several times.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Roman_Bridge_(Trier)", "url": "https://en.wikipedia.org/wiki/Roman_Bridge_(Trier)", "quote": "The nine bridge pillars date from the 2nd century AD, replacing two older, wooden bridges that date at least as far back as 17 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "Trier''s tourist office, Livius and Wikipedia agree that the Moselle crossing at this spot began with a timber pile bridge dendro-dated to 17 BC, tied to the city''s foundation, and that the present stone piers replaced the earlier bridges from 144 AD. The site''s history as a bridge therefore begins in 17 BC, in the 500 BC - 1 AD bucket, not in 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('7e2b3ee7-ffb0-40d3-ae9d-7c8044dd42d2'::uuid, 'period_name', '1 - 500 AD', '< 4500 BC', 'fields-wd1-2026-09-26c-s001:7e2b3ee7-ffb0-40d3-ae9d-7c8044dd42d2:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -4900 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4900) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('7e2b3ee7-ffb0-40d3-ae9d-7c8044dd42d2'::uuid, 'period_start', '1', '-4900', 'fields-wd1-2026-09-26c-s001:7e2b3ee7-ffb0-40d3-ae9d-7c8044dd42d2:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''1'' -> ''-4900''', '[{"source": "https://de.wikipedia.org/wiki/Liste_der_Baudenkm%C3%A4ler_in_Passau", "url": "https://de.wikipedia.org/wiki/Liste_der_Baudenkm%C3%A4ler_in_Passau", "quote": "Entsprechend kann die Altstadthalbinsel mit Unterbrechungen auf eine mehrere tausend Jahre alte Siedlungsgeschichte zurückblicken, die bereits im Mittelneolithikum (Oberlauterbacher Gruppe, ca. 4900–4500 v. Chr.) ihren Anfang nahm.", "outcome": "found"}, {"source": "https://www.limesstrasse.de/deutsche-limes-strasse/limes-strasse/mitgliedsorte/passau", "url": "https://www.limesstrasse.de/deutsche-limes-strasse/limes-strasse/mitgliedsorte/passau", "quote": "Sie bilden die Grundlage zu einer mehrtausendjährigen Siedlungsgeschichte seit dem 5. Jahrtausend v. Chr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "The Bavarian ensemble description of the Passau old town (quoted in the German Wikipedia monument list) says settlement of the Altstadt peninsula began in the Middle Neolithic (Oberlauterbach group, c. 4900-4500 BC), and the Deutsche Limes-Strasse page on Passau gives a settlement history since the 5th millennium BC; the Celtic (2nd century BC) and Roman phases came later, so the start lies before 4500 BC, not in the stored 1 - 500 AD bucket.", "value_page": null}]'::jsonb),
    ('8442fc68-e408-4b2f-9aad-a5f42139685e'::uuid, 'period_name', '< 4500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26c-s001:8442fc68-e408-4b2f-9aad-a5f42139685e:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -3500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3500) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('8442fc68-e408-4b2f-9aad-a5f42139685e'::uuid, 'period_start', '-5000', '-3500', 'fields-wd1-2026-09-26c-s001:8442fc68-e408-4b2f-9aad-a5f42139685e:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-5000'' -> ''-3500''', '[{"source": "https://doam.gov.pk/public/sites/8768", "url": "https://doam.gov.pk/public/sites/8768", "quote": "Relative Chronology: 3500 BCE - 1800 BCE", "outcome": "found"}, {"source": "https://docslib.org/doc/11418773/a-personal-details", "url": "https://docslib.org/doc/11418773/a-personal-details", "quote": "In this Phase (c. 3800-3200 BCE), there was a significant growth in the number of settlements. 153 sites of this Phase are reported from Baluchistan, Kandahar and Northwest Frontier Pakistan. Dabar Kot is the largest site.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "MISSING", "reasoning": "The national register (DOAM) dates Daber Kot from 3500 BCE and the INFLIBNET module (copied on docslib) names it the largest site of the Kechi Beg phase (c. 3800-3200 BCE); the 5th-millennium start in Wikipedia rests on a dictionary''s \"probably\", so the attested start -3500 in the 4500-3000 BC bucket replaces -5000.", "value_page": null}]'::jsonb),
    ('8442fc68-e408-4b2f-9aad-a5f42139685e'::uuid, 'site_type', 'Mound/tumulus', 'Settlement', 'fields-wd1-2026-09-26c-s001:8442fc68-e408-4b2f-9aad-a5f42139685e:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''Mound/tumulus'' -> ''Settlement''', '[{"source": "https://doam.gov.pk/public/sites/8768", "url": "https://doam.gov.pk/public/sites/8768", "quote": "Type: Archaeological Site - Settlement", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Dabarkot", "url": "https://en.wikipedia.org/wiki/Dabarkot", "quote": "The Dabarkot mound is 500 yards in diameter showing the settlement was large in size and of considerable significance.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "MISSING", "reasoning": "DOAM classes Daber Kot as a settlement site and Wikipedia describes it as a tell whose mound shows a large settlement; the mound is a settlement tell, not a burial mound, so Settlement replaces Mound/tumulus.", "value_page": null}]'::jsonb),
    ('90bd1f84-149e-4ee7-98c4-9c14b56298f1'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26c-s001:90bd1f84-149e-4ee7-98c4-9c14b56298f1:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('90bd1f84-149e-4ee7-98c4-9c14b56298f1'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26c-s001:90bd1f84-149e-4ee7-98c4-9c14b56298f1:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, HES (SM2090) and the Canmore record call the broch only Iron Age without a date. The ''very early 1st century AD'' found on SpottingHistory is a copy of a pre-2014 Wikipedia sentence (removed since, and not in the Canmore record it cited), and the Gazetteer for Scotland''s ''early in the 1st C. AD'' repeats the same claim, so no two independent sources date the start. The stored -1000 is in any case earlier than any broch; an empty field beats a wrong one.", "value_page": null}]'::jsonb),
    ('a0a71103-ba22-4eb7-ab4c-321ee37b52bb'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26c-s001:a0a71103-ba22-4eb7-ab4c-321ee37b52bb:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -1000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1000) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a0a71103-ba22-4eb7-ab4c-321ee37b52bb'::uuid, 'period_start', '-500', '-1000', 'fields-wd1-2026-09-26c-s001:a0a71103-ba22-4eb7-ab4c-321ee37b52bb:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-500'' -> ''-1000''', '[{"source": "https://turkisharchaeonews.net/site/amos", "url": "https://turkisharchaeonews.net/site/amos", "quote": "Archaeologists discovered the remains of an apsidal building, which they dated to approximately the 10th century BCE.", "outcome": "found"}, {"source": "https://www.carianmonuments.com/amos/", "url": "https://www.carianmonuments.com/amos/", "quote": "Excavations revealed that this Hellenistic temple was built directly over an Early Iron Age apsidal structure (10th century BCE).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "MISSING", "reasoning": "The 2021 excavations on the acropolis of Amos found an Early Iron Age apsidal building dated to the 10th century BCE, the earliest evidence at the site (Turkish Archaeological News; Carian Monuments); the 10th century BC begins in -1000, in the 1500 - 500 BC bucket rather than the stored 500 BC - 1 AD, so the field is replaced.", "value_page": null}]'::jsonb),
    ('ac47b022-0aee-44d7-8fbf-87797a6a2589'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26c-s001:ac47b022-0aee-44d7-8fbf-87797a6a2589:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://www.livius.org/articles/place/augusta-emerita/", "url": "https://www.livius.org/articles/place/augusta-emerita/", "quote": "Roman city in western Spain, modern Mérida, capital of the", "outcome": "found"}, {"source": "https://www.consorciomerida.org/conjunto", "url": "https://www.consorciomerida.org/conjunto", "quote": "Mérida es una ciudad de origen romano que conserva un importante Conjunto Monumental declarado Patrimonio de la Humanidad.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Augusta_Emerita", "url": "https://en.wikipedia.org/wiki/Augusta_Emerita", "quote": "The city was founded by Roman Emperor Augustus to resettle Emeriti soldiers from the veteran legions of the Cantabrian Wars", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "The Roman ruins of Mérida are the remains of the Roman city and colony Augusta Emerita (theatre, amphitheatre, circus, forum, temples, bridges), as Livius, the Consorcio and Wikipedia describe it; no source calls the ensemble a temple complex, so the type becomes City.", "value_page": null}]'::jsonb),
    ('ad2096b3-cf52-413b-9ec1-8df78713e5e1'::uuid, 'period_name', '500 BC - 1 AD', '< 4500 BC', 'fields-wd1-2026-09-26c-s001:ad2096b3-cf52-413b-9ec1-8df78713e5e1:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -5500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-5500) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ad2096b3-cf52-413b-9ec1-8df78713e5e1'::uuid, 'period_start', '-500', '-5500', 'fields-wd1-2026-09-26c-s001:ad2096b3-cf52-413b-9ec1-8df78713e5e1:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-500'' -> ''-5500''', '[{"source": "https://vici.org/vici/2327/", "url": "https://vici.org/vici/2327/", "quote": "The site was settled uninterruptedly from the Early Chalcolithic Period (5500 BC) through the reign of Emperor Focas (AD 602-610), when an earthquake left the town in ruins.", "outcome": "found"}, {"source": "https://followinghadrianphotography.com/2017/01/05/laodicea-on-the-lycus/", "url": "https://followinghadrianphotography.com/2017/01/05/laodicea-on-the-lycus/", "quote": "Excavations have revealed that the town was continuously inhabited from the Chalcolithic Period (around 5500 BC) until the 7th century AD.", "outcome": "found"}, {"source": "https://kvmgm.ktb.gov.tr/TR-51372/laodikeia-antik-kenti-denizli.html", "url": "https://kvmgm.ktb.gov.tr/TR-51372/laodikeia-antik-kenti-denizli.html", "quote": "Laodikeia’da yapılan kazı çalışmaları, Erken Kalkolitik Dönem (Bakır Çağı, M.Ö. 5500’den M.S. 7. yy.’a kadar kesintisiz yerleşimlerin varlığını ortaya koymuştur.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "MISSING", "reasoning": "Laodicea was refounded as a Seleucid city in 261-253 BC, but the excavations since 2003 show continuous settlement on the site (Rhoas, on Asopos Hill) from the Early Chalcolithic, c. 5500 BC, as the Turkish Ministry of Culture, Vici.org and Following Hadrian all state; the first occupation lies in the < 4500 BC bucket, not the stored 500 BC - 1 AD, so the field is replaced with -5500.", "value_page": null}]'::jsonb),
    ('b0b49640-6fb4-4cb1-b875-01dc81298e34'::uuid, 'site_type', 'Necropolis/tombs complex', 'Dolmen', 'fields-wd1-2026-09-26c-s001:b0b49640-6fb4-4cb1-b875-01dc81298e34:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''Necropolis/tombs complex'' -> ''Dolmen''', '[{"source": "https://journals.ed.ac.uk/lithicstudies/article/view/1943", "url": "https://journals.ed.ac.uk/lithicstudies/article/view/1943", "quote": "The Sardinian dolmen graves, however, had a maximum distribution during the Chalcolithic, as evidenced by most of the finds from excavations.", "outcome": "found"}, {"source": "https://virtualarchaeology.sardegnacultura.it/index.php/en/archaeological-sites/periodo-prenuragico/limuri/detailed-sheets/549-i-dolmen-e-le-ciste-litiche", "url": "https://virtualarchaeology.sardegnacultura.it/index.php/en/archaeological-sites/periodo-prenuragico/limuri/detailed-sheets/549-i-dolmen-e-le-ciste-litiche", "quote": "The more than two hundred dolmen identified so far in Sardinia are concentrated in the north-central part of the island, in the area of Nuoro in particular, and because of their number and their characteristics, are one of the most important megalithic groups in Western Europe (figs. 3, 4).", "outcome": "found"}, {"source": "https://www.museodeidolmen.it/archeoastr.html", "url": "https://www.museodeidolmen.it/archeoastr.html", "quote": "Il dolmen appare in Sardegna alla fine del IV millennio a.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the group of Sardinian dolmens, which the Journal of Lithic Studies, the Region''s Sardinia Virtual Archaeology portal and the Museo dei Dolmen all describe as dolmens (megalithic dolmen graves); the specific canonical type Dolmen fits better than the generic Necropolis/tombs complex.", "value_page": null}]'::jsonb),
    ('b0b49640-6fb4-4cb1-b875-01dc81298e34'::uuid, 'source_url', 'https://virtualarchaeology.sardegnacultura.it/index.php/en/archaeological-sites/periodo-prenuragico/limuri/detailed-sheets/549-i-dolmen-e-le-ciste-litiche', 'https://journals.ed.ac.uk/lithicstudies/article/view/1943', 'fields-wd1-2026-09-26c-s001:b0b49640-6fb4-4cb1-b875-01dc81298e34:source_url', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''https://virtualarchaeology.sardegnacultura.it/index.php/en/archaeological-sites/periodo-prenuragico/limuri/detailed-sheets/549-i-dolmen-e-le-ciste-litiche'' -> ''https://journals.ed.ac.uk/lithicstudies/article/view/1943''', '[{"source": "https://journals.ed.ac.uk/lithicstudies/article/view/1943", "url": "https://journals.ed.ac.uk/lithicstudies/article/view/1943", "quote": "The Sardinian dolmen graves, however, had a maximum distribution during the Chalcolithic, as evidenced by most of the finds from excavations.", "outcome": "found"}, {"source": "https://virtualarchaeology.sardegnacultura.it/index.php/en/archaeological-sites/periodo-prenuragico/limuri/detailed-sheets/549-i-dolmen-e-le-ciste-litiche", "url": "https://virtualarchaeology.sardegnacultura.it/index.php/en/archaeological-sites/periodo-prenuragico/limuri/detailed-sheets/549-i-dolmen-e-le-ciste-litiche", "quote": "The more than two hundred dolmen identified so far in Sardinia are concentrated in the north-central part of the island, in the area of Nuoro in particular, and because of their number and their characteristics, are one of the most important megalithic groups in Western Europe (figs. 3, 4).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The stored Virtual Archaeology sheet is a detail page of the Li Muri necropolis on dolmens and lithic cists in general, whereas Cicilloni and Cabras'' open-access Journal of Lithic Studies article (GIS-based landscape analysis of megalithic graves in the Island of Sardinia) is a scholarly page about the Sardinian dolmens themselves; there is no Wikipedia article on the group.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('b36ba7d0-962c-48cc-93c2-717890bb64e7'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26c-s001:b36ba7d0-962c-48cc-93c2-717890bb64e7:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://www.mustfarm.com/bronze-age-settlement/", "url": "https://www.mustfarm.com/bronze-age-settlement/", "quote": "Between 2015-16 archaeologists from the Cambridge Archaeological Unit excavated the remains of a Late Bronze Age (850BC) pile-dwelling settlement.", "outcome": "found"}, {"source": "https://peterborougharchaeology.org/peterborough-archaeological-sites/must-farm/", "url": "https://peterborougharchaeology.org/peterborough-archaeological-sites/must-farm/", "quote": "The settlement consisted of houses built on a series of piles, or stilts, sunk into a river channel below.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Must_Farm", "url": "https://en.wikipedia.org/wiki/Must_Farm", "quote": "The settlement is exceptionally well preserved because of its sudden destruction by catastrophic fire and subsequent collapse onto oxygen-depleted river silts.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "The excavators, Peterborough Archaeology and Wikipedia all call Must Farm a settlement - a small palisaded group of stilt houses, not a town or city - so the most specific canonical type is Settlement rather than the umbrella City/town/settlement.", "value_page": null}]'::jsonb),
    ('b67a72ea-cdd7-4feb-9847-aee79adcd9be'::uuid, 'period_name', '< 4500 BC', NULL, 'fields-wd1-2026-09-26c-s001:b67a72ea-cdd7-4feb-9847-aee79adcd9be:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b67a72ea-cdd7-4feb-9847-aee79adcd9be'::uuid, 'period_start', '-5000', NULL, 'fields-wd1-2026-09-26c-s001:b67a72ea-cdd7-4feb-9847-aee79adcd9be:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-5000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "Henmore Brook is a 20 km tributary of the River Dove in Derbyshire, a natural watercourse, not a monument; Wikipedia only mentions undated Palaeolithic sites, barrows and a Roman settlement elsewhere in its valley, and no source dates a start for the brook as a site, so the unsupported -5000 is cleared.", "value_page": null}]'::jsonb),
    ('c053a09d-ff4f-4277-9776-5c246cdfca79'::uuid, 'site_type', 'City/town/settlement', 'Town', 'fields-wd1-2026-09-26c-s001:c053a09d-ff4f-4277-9776-5c246cdfca79:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''City/town/settlement'' -> ''Town''', '[{"source": "https://en.wikipedia.org/wiki/Lactodurum", "url": "https://en.wikipedia.org/wiki/Lactodurum", "quote": "Lactodorum was a town in the Roman province of Britannia", "outcome": "found"}, {"source": "https://www.british-history.ac.uk/rchme/northants/vol4/pp149-160", "url": "https://www.british-history.ac.uk/rchme/northants/vol4/pp149-160", "quote": "The major monument is the Roman town of Lactodurum (3), the site of which is occupied by modern Towcester.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the RCHME inventory both describe Lactodurum as a Roman town (a walled roadside town on Watling Street under modern Towcester), so the specific type Town replaces the combined City/town/settlement.", "value_page": null}]'::jsonb),
    ('c06cb387-e065-4bcd-bbbe-a6b9d1a4082d'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26c-s001:c06cb387-e065-4bcd-bbbe-a6b9d1a4082d:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c06cb387-e065-4bcd-bbbe-a6b9d1a4082d'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26c-s001:c06cb387-e065-4bcd-bbbe-a6b9d1a4082d:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "Only Wikipedia (Harrow Way and Pilgrims'' Way articles, one source family) states the route was ''dated by archaeological finds to 600 – 450 BC, but probably in existence since the Stone Age'', without naming the finds, and the pages repeating it (Wikishire, a blog) copy that wording; no independent second source dates the start, so the field is cleared.", "value_page": null}]'::jsonb),
    ('c1fe860b-f047-431e-8384-489fa1686f50'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26c-s001:c1fe860b-f047-431e-8384-489fa1686f50:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -2000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c1fe860b-f047-431e-8384-489fa1686f50'::uuid, 'period_start', '-1500', '-2000', 'fields-wd1-2026-09-26c-s001:c1fe860b-f047-431e-8384-489fa1686f50:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-1500'' -> ''-2000''', '[{"source": "https://madainproject.com/eleusis", "url": "https://madainproject.com/eleusis", "quote": "The remains in the archaeological site date from the Early Bronze Age (circa 2000 BCE) through the late fourth century CE", "outcome": "found"}, {"source": "https://elefsina.gr/en/myth-history-excavations", "url": "https://elefsina.gr/en/myth-history-excavations", "quote": "A sanctuary and settlement dating back to before 1580 BC (Middle Helladic period 2000-1580 BC) were also revealed by archaeological excavations", "outcome": "found"}, {"source": "https://topostext.org/place/380235PEle", "url": "https://topostext.org/place/380235PEle", "quote": "The extensive Middle Bronze Age cemetery (2000-1600 BC) is one of the most important in the Aegean.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "The Madain Project dates the earliest remains in the archaeological site to c. 2000 BCE, the Municipality of Elefsina reports a sanctuary and settlement of the Middle Helladic period (2000-1580 BC), and ToposText (from the Ministry''s description) a Middle Bronze Age cemetery of 2000-1600 BC. The start therefore lies c. 2000 BC, in the 3000 - 1500 BC bucket, not at the stored -1500.", "value_page": null}]'::jsonb),
    ('c1fe860b-f047-431e-8384-489fa1686f50'::uuid, 'source_url', 'https://www.britannica.com/place/Eleusis-ancient-city-Greece', 'https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis', 'fields-wd1-2026-09-26c-s001:c1fe860b-f047-431e-8384-489fa1686f50:source_url', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''https://www.britannica.com/place/Eleusis-ancient-city-Greece'' -> ''https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis''', '[{"source": "https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis", "url": "https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis", "quote": "Le sanctuaire d''Éleusis ou sanctuaire des Grandes Déesses est le lieu d''initiation des citoyens d''Athènes et d''autres cités grecques aux rites des mystères d''Éleusis", "outcome": "found"}, {"source": "https://topostext.org/place/380235SEle", "url": "https://topostext.org/place/380235SEle", "quote": "Eleusinian Demeter, Site of the Eleusinian mystery cult of Demeter and Kore, Eleusis in Attiki", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "The stored Britannica page refuses automated requests (403). English Wikipedia has no article on the ancient site (''Eleusis'' redirects to the modern town Elefsina), but French Wikipedia has one on the archaeological sanctuary of Eleusis itself; ToposText, an independent source, names the same site.", "value_page": {"lang": "fr", "problem": null, "resolved_title": "Sanctuaire d''Éleusis", "unreadable": false, "wikibase_item": "Q94299853"}}]'::jsonb),
    ('cbc93ea2-6ae5-4be6-a320-254960a60ab7'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26c-s001:cbc93ea2-6ae5-4be6-a320-254960a60ab7:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cbc93ea2-6ae5-4be6-a320-254960a60ab7'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26c-s001:cbc93ea2-6ae5-4be6-a320-254960a60ab7:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "The grave field''s main use is dated 500 BC to 500 AD (en/sv Wikipedia, GuidebookSweden), but Naturkartan and the Stockholm University excavation reports (Fahlander & Vinberg 2023) record a few earlier graves from the Younger Bronze Age plus Stone Age settlement remains on the site, and no source gives a year for that earliest phase; -500 would be wrong and -1500 cannot be sourced, so the field is emptied.", "value_page": null}]'::jsonb),
    ('cee33cc0-9de5-493c-b43b-82678a6b1d8b'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26c-s001:cee33cc0-9de5-493c-b43b-82678a6b1d8b:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start 1 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cee33cc0-9de5-493c-b43b-82678a6b1d8b'::uuid, 'period_start', '-500', '1', 'fields-wd1-2026-09-26c-s001:cee33cc0-9de5-493c-b43b-82678a6b1d8b:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-500'' -> ''1''', '[{"source": "https://ourense.gal/turismo/en/la-ciudad/un-poco-de-historia/", "url": "https://ourense.gal/turismo/en/la-ciudad/un-poco-de-historia/", "quote": "In the 1st century the Romans arrived in Galicia, and at this time a strategic bridge was built over river Minho", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Las_Burgas", "url": "https://es.wikipedia.org/wiki/Las_Burgas", "quote": "En el Área Arqueológica de Las Burgas conviven desde mediados del siglo I d. C. dos tipos de usos de estas aguas.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "The city''s tourism office dates the Roman arrival, the bridge and its garrison around which Ourense grew to the 1st century, and the Las Burgas article dates the Roman thermal use of the springs at the city''s core from the mid-1st century AD; the earlier castros are separate hillforts, so the attested start of the city is the 1st century AD, not the stored 500 BC.", "value_page": null}]'::jsonb),
    ('d074c899-cdcb-48db-9207-1ebea88ce927'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26c-s001:d074c899-cdcb-48db-9207-1ebea88ce927:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d074c899-cdcb-48db-9207-1ebea88ce927'::uuid, 'period_start', '-4500', '-3000', 'fields-wd1-2026-09-26c-s001:d074c899-cdcb-48db-9207-1ebea88ce927:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-4500'' -> ''-3000''', '[{"source": "https://www.asterousiacrete.gr/en/points-of-interest/listing/%CF%84rypiti-during-the-4th-millennium-bc-to-the-byzantine-period/", "url": "https://www.asterousiacrete.gr/en/points-of-interest/listing/%CF%84rypiti-during-the-4th-millennium-bc-to-the-byzantine-period/", "quote": "The principal Prepalatial settlement was established on the hill of Adami Korfali, where excavation uncovered a densely built community with two successive architectural phases dating to the beginning of the third millennium BC.", "outcome": "found"}, {"source": "https://asterousiatrails.com/en/i-trypiti-and-the-prehistoric-coastal-settlement/", "url": "https://asterousiatrails.com/en/i-trypiti-and-the-prehistoric-coastal-settlement/", "quote": "In the Trypiti area, atop the rocky hill known as Papouri or Adami Korfali, lies one of the most important Early Minoan settlements in southern Crete, which flourished during the 3rd millennium BC.", "outcome": "found"}, {"source": "https://lithoscrete.com/crete/tripiti-minoan-settlement/", "url": "https://lithoscrete.com/crete/tripiti-minoan-settlement/", "quote": "He found 36 rectangular rooms and pottery shards dating back to 3000 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The Asterousia heritage pages (citing the excavator Vasilakis) date the Early Minoan hilltop settlement of Trypiti to the beginning of the 3rd millennium BC, and the Lithos Crete guide dates its rooms and pottery back to 3000 BC; the 4th-millennium traces belong to the separate Adami Zonaria rock shelters, so the settlement''s start is c. 3000 BC, outside the stored 4500-3000 BC bucket.", "value_page": null}]'::jsonb),
    ('d2bfe5ff-6e7a-46ad-b9ae-69723cb08563'::uuid, 'period_name', '4500 - 3000 BC', '1000 - 1500 AD', 'fields-wd1-2026-09-26c-s001:d2bfe5ff-6e7a-46ad-b9ae-69723cb08563:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start 1329 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1329) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d2bfe5ff-6e7a-46ad-b9ae-69723cb08563'::uuid, 'period_start', '-4000', '1329', 'fields-wd1-2026-09-26c-s001:d2bfe5ff-6e7a-46ad-b9ae-69723cb08563:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-4000'' -> ''1329''', '[{"source": "https://www.bouger-voyager.com/visiter-olmeto/", "url": "https://www.bouger-voyager.com/visiter-olmeto/", "quote": "Goglermo et Gotifredo della Rocca, quittant le site de la Rocca, construisirent le grand village d’Ulmetu entre 1329 et 1353.", "outcome": "found"}, {"source": "https://pop.culture.gouv.fr/notice/merimee/IA2A000834", "url": "https://pop.culture.gouv.fr/notice/merimee/IA2A000834", "quote": "Ces deux quartiers possèdent un noyau de la fin du Moyen Age, comptant chacun deux maisons fortes et plusieurs maisons du 15e siècle et du 16e siècle.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the village of Olmeto (Ulmetu): a local heritage text says the della Rocca built the village between 1329 and 1353, and the Ministry of Culture''s inventory (POP) dates the two original quarters to a late-medieval nucleus with 15th-century houses, so the village begins in the 1000 - 1500 AD bucket. The stored -4000 comes from excavations at Monte Barbatu, a separate hill site in the commune, not from the village.", "value_page": null}]'::jsonb),
    ('d3272ca0-0c72-4c97-a745-762e9ed77416'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26c-s001:d3272ca0-0c72-4c97-a745-762e9ed77416:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -900 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-900) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d3272ca0-0c72-4c97-a745-762e9ed77416'::uuid, 'period_start', '-3000', '-900', 'fields-wd1-2026-09-26c-s001:d3272ca0-0c72-4c97-a745-762e9ed77416:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-3000'' -> ''-900''', '[{"source": "https://www.sardegnacultura.it/en/articles/fluminimaggiore-tempio-di-antas", "url": "https://www.sardegnacultura.it/en/articles/fluminimaggiore-tempio-di-antas", "quote": "From the beginning of the Iron Age, in the 9th century BC, the site had a funerary significance, perhaps linked to ancestor worship, as evidenced by a series of single-person shaft tombs discovered near the podium.", "outcome": "found"}, {"source": "https://it.wikipedia.org/wiki/Tempio_di_Antas", "url": "https://it.wikipedia.org/wiki/Tempio_di_Antas", "quote": "appartenenti probabilmente ad una necropoli più estesa risalente alla prima età del ferro (IX - VIII secolo a.C.).", "outcome": "found"}, {"source": "https://www.sardegnaturismo.it/it/esplora/tempio-di-antas", "url": "https://www.sardegnaturismo.it/it/esplora/tempio-di-antas", "quote": "Nel sito, sacro già in età nuragica (IX secolo a.C.), alla fine dell’età del Ferro si stanziarono i cartaginesi, poi (a metà III a.C.) giunsero i romani.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "SardegnaCultura and SardegnaTurismo date the beginning of the Antas sanctuary site to the Nuragic Iron Age, the 9th century BC (shaft tombs by the podium), and Italian Wikipedia dates that necropolis to the 9th-8th century BC, before the Punic temple of c. 500 BC; the start c. 900 BC lies in the 1500-500 BC bucket, not the stored 3000-1500 BC one.", "value_page": null}]'::jsonb),
    ('debb506e-ab0d-4e03-876e-320c31ee59d2'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26c-s001:debb506e-ab0d-4e03-876e-320c31ee59d2:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('debb506e-ab0d-4e03-876e-320c31ee59d2'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26c-s001:debb506e-ab0d-4e03-876e-320c31ee59d2:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, Pleiades, the Greek cave guides (cretanbeaches, arxeion-politismou, petronikolis) all say only that Stravomyti Cave was first used in the Neolithic, without a year, century or millennium; no readable source dates the start numerically, so the stored -4000 cannot be sourced and the field is emptied.", "value_page": null}]'::jsonb),
    ('dee36d33-1911-4cc8-9aa7-c7ad207298d1'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26c-s001:dee36d33-1911-4cc8-9aa7-c7ad207298d1:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('dee36d33-1911-4cc8-9aa7-c7ad207298d1'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26c-s001:dee36d33-1911-4cc8-9aa7-c7ad207298d1:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, the Megalithic Portal and Visit South Devon call Slapton Castle (Stokenham, Devon) only an Iron Age hillfort, with no year, century or millennium; the only dated page, the South Devon AONB''s Stokenham sheet, gives the generic Iron Age span ''700 BC - 50 AD'' for the parish, not a date for the fort, and the Devon HER record (MDV8371) sits on the Heritage Gateway the checker cannot read. No two independent sources date the fort''s start.", "value_page": null}]'::jsonb),
    ('e7ab9b35-e0bb-4fe4-a1cb-fbe5a17c63d6'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26c-s001:e7ab9b35-e0bb-4fe4-a1cb-fbe5a17c63d6:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/Dankirke", "url": "https://en.wikipedia.org/wiki/Dankirke", "quote": "Dankirke was a Danish Iron Age settlement in south-west Jutland, located near the later town of Ribe.", "outcome": "found"}, {"source": "https://lex.dk/Dankirke", "url": "https://lex.dk/Dankirke", "quote": "Dankirke, jernalderboplads nær Ribe fra århundrederne f.Kr. til ind i 700-t.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia calls Dankirke an Iron Age settlement and Den Store Danske (lex.dk) an Iron Age ''boplads'' (settlement) near Ribe; the most specific canonical type is Settlement rather than the combined City/town/settlement.", "value_page": null}]'::jsonb),
    ('e7e82839-72a2-466c-93ee-7292571e8506'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26c-s001:e7e82839-72a2-466c-93ee-7292571e8506:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e7e82839-72a2-466c-93ee-7292571e8506'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26c-s001:e7e82839-72a2-466c-93ee-7292571e8506:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "clear", "status": "MISSING", "reasoning": "The sources call the West Woods long barrow Early Neolithic and record Mesolithic to Iron Age activity in the wood (Wikipedia; Nash et al. 2020 in Science Advances; Megalithic Portal; Exploring Avebury), but none gives a year, century or millennium for when the site begins. The only dated statement, sarsens taken for Stonehenge around 2500 BC, is a later use, not the start. No two independent sources date the start.", "value_page": null}]'::jsonb),
    ('ed7a8c35-1066-4b08-8bf4-3496a1ad0c81'::uuid, 'site_type', 'City/town/settlement', 'Village', 'fields-wd1-2026-09-26c-s001:ed7a8c35-1066-4b08-8bf4-3496a1ad0c81:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''City/town/settlement'' -> ''Village''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=19023", "url": "https://www.megalithic.co.uk/article.php?sid=19023", "quote": "The team excavated two graves in the ancient Mixtec village of Tayata, which is in the state of Oaxaca", "outcome": "found"}, {"source": "https://opensiuc.lib.siu.edu/theses/403/", "url": "https://opensiuc.lib.siu.edu/theses/403/", "quote": "use of animals and animal imagery in early Mesoamerican villages. I look at the faunal remains excavated from Early and Middle Formative (1350-850 B.C) domestic and ceremonial contexts at the Mixteca Alta site of Tayata, Oaxaca.", "outcome": "found"}, {"source": "https://journals.openedition.org/jsa/12586", "url": "https://journals.openedition.org/jsa/12586", "quote": "Figurine Embodiment and Household Ritual in an Early Mixtec Village", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "Tayata (Mixteca Alta, Oaxaca; the Megalithic Portal record gives 17.35N 97.57W, the stored point) is described by the Megalithic Portal as ''the ancient Mixtec village of Tayata'', by the Southern Illinois University thesis on its fauna as one of the ''early Mesoamerican villages'', and by the Journal de la Societe des Americanistes article on its figurines as ''an Early Mixtec Village''. Village is the specific canonical type these independent sources name, more specific than the stored generic City/town/settlement.", "value_page": null}]'::jsonb),
    ('f0b20fa9-aab2-400d-bfa8-24af297bb993'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26c-s001:f0b20fa9-aab2-400d-bfa8-24af297bb993:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/Kastros", "url": "https://en.wikipedia.org/wiki/Kastros", "quote": "Kastros is an early Neolithic settlement in Cyprus.", "outcome": "found"}, {"source": "http://www.whatson-northcyprus.com/interest/dipkarpaz/kastros.htm", "url": "http://www.whatson-northcyprus.com/interest/dipkarpaz/kastros.htm", "quote": "Kastros was excavated between 1970 and ''73 by a French team. They discovered that the settlement consisted of small, round, houses, with a diameter of less than 3m.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "Both sources describe Kastros as a Neolithic settlement of small round houses - a hamlet, not a city or town - so the most specific canonical type is Settlement.", "value_page": null}]'::jsonb),
    ('f5131959-47d4-4052-a049-a92f51837614'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26c-s001:f5131959-47d4-4052-a049-a92f51837614:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -500', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('f921cb05-ab49-4bc9-b9a0-3dae48ee3e5a'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26c-s001:f921cb05-ab49-4bc9-b9a0-3dae48ee3e5a:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start -1400 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1400) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('f921cb05-ab49-4bc9-b9a0-3dae48ee3e5a'::uuid, 'period_start', '-3000', '-1400', 'fields-wd1-2026-09-26c-s001:f921cb05-ab49-4bc9-b9a0-3dae48ee3e5a:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-replace): ''-3000'' -> ''-1400''', '[{"source": "https://www.delange.org/Pucara3/Pucara3.html", "url": "https://www.delange.org/Pucara3/Pucara3.html", "quote": "Epoch 1, the initial pre-Pukara occupation, which dates from about 1400 BC.", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Pucar%C3%A1_(sitio_arqueol%C3%B3gico)", "url": "https://es.wikipedia.org/wiki/Pucar%C3%A1_(sitio_arqueol%C3%B3gico)", "quote": "El asentamiento fue ocupado entre los años 1400 a. C. y 600 d. C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "replace", "status": "MISSING", "reasoning": "The DeLange page, summarising the research chronology of the Pukara site, puts its initial (pre-Pukara) occupation at about 1400 BC, and Spanish Wikipedia''s article on the archaeological complex says the settlement was occupied from 1400 BC to AD 600. The start c. 1400 BC falls in the 1500-500 BC bucket, not the stored 3000-1500 BC one; English Wikipedia''s unsourced-looking ''as early as 1,800 BC'' is not supported by a second independent source.", "value_page": null}]'::jsonb),
    ('fa425008-1b60-43fa-8ac9-31b17fba3821'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26c-s001:fa425008-1b60-43fa-8ac9-31b17fba3821:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('fa425008-1b60-43fa-8ac9-31b17fba3821'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26c-s001:fa425008-1b60-43fa-8ac9-31b17fba3821:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "The stored 500 BC is contradicted by every source: Wikipedia, the Gunaikurnai Land and Waters Aboriginal Corporation and austhrutime date the first occupation of New Guinea II cave to c. 21,900 BP / almost 21,000 years ago (Pleistocene), but no readable page states that start as a BC year, century or millennium, and BP/years-ago dates are not read, so the wrong value is emptied.", "value_page": null}]'::jsonb),
    ('fab3989d-2c06-40cc-9d22-c7fb58e5e94f'::uuid, 'period_name', '< 4500 BC', NULL, 'fields-wd1-2026-09-26c-s001:fab3989d-2c06-40cc-9d22-c7fb58e5e94f:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('fab3989d-2c06-40cc-9d22-c7fb58e5e94f'::uuid, 'period_start', '-6000', NULL, 'fields-wd1-2026-09-26c-s001:fab3989d-2c06-40cc-9d22-c7fb58e5e94f:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-6000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "Every source found (English and Portuguese Wikipedia, Frontiers in Microbiology 2024, the Unaí municipality) dates the first hunter-gatherer occupation only in BP (c. 12,000-8,125 BP; oldest layer 10,190 BP); no readable page states that start as a BC year, century or millennium, so the start is not attested in a readable form and the field is emptied.", "value_page": null}]'::jsonb),
    ('fbe0c4cf-1863-4930-9bca-1557de689b67'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26c-s001:fbe0c4cf-1863-4930-9bca-1557de689b67:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('fbe0c4cf-1863-4930-9bca-1557de689b67'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26c-s001:fbe0c4cf-1863-4930-9bca-1557de689b67:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the 2023 announcements by the Generalitat, IPHES, URV and IBE date the earliest occupation of Cova Simanya to Neanderthal remains of more than 50,000 years ago (42-49 ka), so the stored 1 AD is wrong; but every source gives this start only as years ago or ka, never as a BC year, century or millennium, so no readable start year can be quoted and the field is emptied.", "value_page": null}]'::jsonb),
    ('fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26c-s001:fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a:period_name', 'fields-wd1-2026-09-26c-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26c-s001:fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a:period_start', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "clear", "status": "MISSING", "reasoning": "The route is a present-day itinerary; its component sites begin at very different dates (Celtic Sirmium and Singidunum in the 3rd century BC, Viminacium in the 1st century AD, Mediana in the 4th century AD). No source dates a start of the route itself as an ancient site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a'::uuid, 'site_type', 'Road/avenue/trackway', NULL, 'fields-wd1-2026-09-26c-s001:fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a:site_type', 'fields-wd1-2026-09-26c-s001 (wd1-clear): ''Road/avenue/trackway'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and Wikidata describe the Roman Emperors Route as a tourism and archaeology project / scenic route connecting archaeological sites, not as an ancient road, so the stored Road/avenue/trackway misdescribes it, and no canonical type names a modern cultural itinerary. No two sources describe it as any of the canonical types.", "value_page": null}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 89;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _fields_wd1_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'lat' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'lon' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'geom' THEN p.new_value::geometry IS NOT DISTINCT FROM p.old_value::geometry OR p.new_value IS NULL
                WHEN 'period_start' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'site_type' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'source_url' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.old_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.old_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.old_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.old_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _fields_wd1_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.new_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD')
                WHEN 'site_type' THEN p.new_value NOT IN ('City', 'Town', 'Village', 'Settlement', 'Urban', 'Villa', 'City/town/settlement', 'Residence/villa/farmhouse', 'City/town/settlement, Pyramid complex', 'Castle', 'Citadel', 'Fort', 'Fortress', 'Military', 'Wall', 'Gate', 'Fortress/citadel', 'Castle/palace', 'Gate/archway/bridge', 'Fortification', 'Church', 'Mosque', 'Temple', 'Monastery', 'Sacred site', 'Sanctuary', 'Religious', 'Temple complex', 'Church/cathedral', 'Minaret/tower', 'Stone cross', 'Cemetery', 'Necropolis', 'Tomb', 'Burial', 'Funerary', 'Necropolis/tombs complex', 'Barrow', 'Mound/tumulus', 'Cairn', 'Elongated skulls', 'Megalithic', 'Megalithic stones', 'Megalithic structures', 'Megalithic statues', 'Megalithic walls', 'Stone circle', 'Dolmen', 'Standing stone', 'Henge', 'Timber circle', 'Polygonal masonry', 'Cave', 'Cave Structures', 'Rock relief/carving', 'Rock art', 'Petroglyphs', 'Sculptured stone', 'Cave Structures, Rock art', 'Geoglyphs', 'Road', 'Bridge', 'Mine', 'Quarry', 'Infrastructure', 'Road/avenue/trackway', 'Reservoir/aqueduct/canal', 'Mine/quarry', 'Earthwork', 'Well', 'Aqueduct', 'Bath', 'Harbor', 'Port', 'Underwater structures', 'Shipwreck', 'Monument', 'Memorial', 'Stadium', 'Theater', 'Theatre', 'Forum', 'Palace', 'Pyramid complex', 'Museum', 'Amphitheatre', 'Scheduled monument', 'Heritage site', 'Archaeological site', 'Site', 'Ruin', 'Inscription', 'Natural feature', 'Impact crater', 'Geological interest', 'Magnetic anomaly', 'Unknown')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _fields_wd1_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WD1/structured-fields', '2026-09-26c_fields-wd1-s001', r.change_key, 'two_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'WD1 field correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.new_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.new_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.new_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-09-26c_fields-wd1-s001'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-26c_fields-wd1-s001'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: this run stamp journalled % row(s) outside unified_sites.(lat, lon, geom, period_start, period_name, site_type, source_url)', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a geom that is not their point
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd1_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd1_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('lat', 'lon', 'geom')) AND u.geom IS DISTINCT FROM ST_SetSRID(ST_MakePoint(u.lon, u.lat), 4326);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned site(s) hold a geom that is not their point', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a period_name that is not the bucket of their period_start
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd1_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd1_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('period_start', 'period_name')) AND u.period_name IS DISTINCT FROM (CASE WHEN u.period_start IS NULL THEN NULL WHEN u.period_start < -4500 THEN '< 4500 BC' WHEN u.period_start < -3000 THEN '4500 - 3000 BC' WHEN u.period_start < -1500 THEN '3000 - 1500 BC' WHEN u.period_start < -500 THEN '1500 - 500 BC' WHEN u.period_start < 1 THEN '500 BC - 1 AD' WHEN u.period_start < 500 THEN '1 - 500 AD' WHEN u.period_start < 1000 THEN '500 - 1000 AD' WHEN u.period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned site(s) hold a period_name that is not the bucket of their period_start', bad;
    END IF;

    RAISE NOTICE 'WD1 field correction: % of % planned cell(s) changed and journalled over 46 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-26c_fields-wd1-s001'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WD1/structured-fields'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-09-26c_fields-wd1-s001' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'lat' THEN u.lat IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'lon' THEN u.lon IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'geom' THEN u.geom IS NOT DISTINCT FROM l.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS NOT DISTINCT FROM l.new_value::integer
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS NOT DISTINCT FROM l.new_value::text
                ELSE false END)
UNION ALL
SELECT 'curated rows whose period_name is not the bucket of period_start', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND period_name IS DISTINCT FROM (CASE WHEN period_start IS NULL THEN NULL WHEN period_start < -4500 THEN '< 4500 BC' WHEN period_start < -3000 THEN '4500 - 3000 BC' WHEN period_start < -1500 THEN '3000 - 1500 BC' WHEN period_start < -500 THEN '1500 - 500 BC' WHEN period_start < 1 THEN '500 BC - 1 AD' WHEN period_start < 500 THEN '1 - 500 AD' WHEN period_start < 1000 THEN '500 - 1000 AD' WHEN period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END)
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
